_GOLD = "\x1b[1;38;2;250;200;36m"
_RESET = "\x1b[0m"
_ANSI = re.compile(r"\x1b\[[0-9;]*m")


def _console_available():
    """Is a real console attached, and can it do ANSI?

    Asks the OS handle, NOT sys.stdout.isatty(). isatty() cannot answer this inside
    ComfyUI: ComfyUI-Manager replaces sys.stdout with a logger whose isatty() is a
    hardcoded `return False` (its prestartup_script.py), so anything gating colour on
    it loses colour for reasons that have nothing to do with the terminal. Measured -
    a bare console reports isatty True, and the same console under Manager reports
    False.

    The handle is also still the right answer for the case isatty() was guarding:
    with stdout redirected to a file GetConsoleMode fails, and the plain text is used.
    """
    if os.name != "nt":
        try:
            return sys.__stdout__.isatty()
        except Exception:
            return False
    try:
        import ctypes

        handle = ctypes.windll.kernel32.GetStdHandle(-11)   # STD_OUTPUT_HANDLE
        mode = ctypes.c_ulong()
        if not ctypes.windll.kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
            return False                                     # redirected, not a console
        ENABLE_VIRTUAL_TERMINAL_PROCESSING = 0x0004
        # The return value matters and must not be dropped: a console older than
        # Windows 10 1511 does not know the VT flag and fails here, and emitting the
        # escape codes anyway prints them as literal garbage across 45 lines.
        return bool(ctypes.windll.kernel32.SetConsoleMode(
            handle, mode.value | ENABLE_VIRTUAL_TERMINAL_PROCESSING))
    except Exception:
        return False


def _terminal_width():
    """Columns available, best effort. 80 is the honest pessimistic default."""
    try:
        import shutil

        return shutil.get_terminal_size(fallback=(80, 24)).columns
    except Exception:
        return 80


def _encodable(text, stream):
    """Can this stream actually write these characters?

    Not a formality. The colour art uses the half-block glyphs and the footer a money
    bag, and a Windows console on cp1252 encodes none of them — it raises
    UnicodeEncodeError mid-write, which under a bare `except` looks exactly like the
    banner having been switched off. Checked up front so the ASCII fallback is used
    instead of nothing being drawn at all.
    """
    encoding = getattr(stream, "encoding", None) or "ascii"
    try:
        text.encode(encoding)
        return True
    except (UnicodeEncodeError, LookupError, TypeError):
        return False


def _wants_colour(stream):
    if os.environ.get("NO_COLOR"):
        return False
    return _console_available()


def _footer(colour, node_count, money, sep):
    tail = ("arkennemasis loaded" if node_count is None
            else "arkennemasis %s %d nodes loaded" % (sep, node_count))
    line = ("  %s  %s" % (tail, money)).center(COLUMNS)
    return (_GOLD + line + _RESET) if colour else line


def _compact(colour, node_count, money="\U0001f4b0", sep="·"):
    """One line, for a console too narrow to hold the art."""
    tail = ("arkennemasis loaded" if node_count is None
            else "arkennemasis %s %d nodes loaded" % (sep, node_count))
    if colour:
        return ("\n" + _YELLOW + " Money Follows " + _RESET
                + _RED + " My Brother " + _RESET
                + _GOLD + "  " + tail + " " + money + _RESET + "\n")
    return "\n Money Follows / My Brother  %s %s\n" % (tail, money)


def render(colour=True, node_count=None, money="\U0001f4b0", sep="·"):
    """The whole banner as one string. `money`/`sep` drop to ASCII for a dumb console."""
    art = _ART if colour else _PLAIN
    return "\n" + art + "\n" + _footer(colour, node_count, money, sep) + "\n"


def show(node_count=None, stream=None):
    """Print it. Never raises, and never half-prints."""
    if os.environ.get("ARK_BANNER", "1").strip().lower() in ("0", "false", "no", "off"):
        return
    stream = stream or sys.stdout
    try:
        # A console narrower than the art would wrap all 45 rows into pulp, which is
        # worse than no banner. Say the same thing in one line instead.
        narrow = _terminal_width() < COLUMNS

        # Best first, each a step less demanding of the terminal: full colour, then
        # plain glyphs, then pure ASCII for a console stuck on a codepage that has
        # neither a money bag nor a middle dot.
        colour = _wants_colour(stream)
        if narrow:
            candidates = [_compact(colour, node_count),
                          _ANSI.sub("", _compact(False, node_count)),
                          _ANSI.sub("", _compact(False, node_count,
                                                 money="$$$", sep="-"))]
        else:
            candidates = []
            if colour:
                candidates.append(render(True, node_count))
            candidates.append(_ANSI.sub("", render(False, node_count)))
            candidates.append(_ANSI.sub("", render(False, node_count,
                                                   money="$$$", sep="-")))

        for text in candidates:
            if _encodable(text, stream):
                stream.write(text)      # ONE write - see the module docstring
                stream.flush()
                return
    except Exception:
        pass


if __name__ == "__main__":
    show(node_count=None)
